// Cart amount in yen before any rounding. `discount` is the customer's discount
// rate (0.1 = 10%). Carts with 10 or more lines get an extra 5% bulk discount,
// applied once, after the customer's discount.
export function unroundedTotal(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  return subtotal * (1 - discount) * (1 - bulk);
}

// Cart total in yen. Fractions of a yen are dropped.
export function total(items, discount = 0) {
  // Snap away binary floating-point noise first, so that an exact amount such as
  // 100 * (1 - 0.07) = 92.99999999999999 is not floored down to 92.
  return Math.floor(Math.round(unroundedTotal(items, discount) * 1e6) / 1e6);
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
